import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Narrow, reversible edits to existing skill145 WORLD release and loot consumer. */
public final class TamedLifecycleMethods {
 static final String P="local/lito381/server/",H=P+"NativeTamedWorldLifecycle";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(P+n+".class"))).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static MethodNode method(ClassNode c,String n){return c.methods.stream().filter(m->m.name.equals(n)).findFirst().orElseThrow();}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n.getOpcode()<0);return n;}
 static void patch(ClassNode c){int changed=0;
  if(c.name.equals(P+"ClientSession")){
   var m=method(c,"releaseCompanionToNature");int transfers=0;
   for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call){
    if(call.name.equals("releaseClassicWorldTamedMonster")){if(!call.owner.equals(P+"GameHub"))throw new AssertionError();var extra=new InsnList();extra.add(new VarInsnNode(Opcodes.ALOAD,0));extra.add(new VarInsnNode(Opcodes.ALOAD,1));m.instructions.insertBefore(call,extra);call.setOpcode(Opcodes.INVOKESTATIC);call.owner=H;call.name="release";call.desc="(L"+P+"GameHub;IIJL"+P+"BattleCompanion$Snapshot;L"+P+"ClientSession;L"+P+"BattleCompanion;)L"+P+"ClassicWorldMonsterPopulation$TamedRelease;";changed++;}
    if(call.name.equals("transferCompanionItems")&&++transfers==2){var pet=prev(call);var pc=prev(pet);if(!(pet instanceof VarInsnNode v&&v.getOpcode()==Opcodes.ALOAD&&v.var==1&&pc instanceof VarInsnNode v0&&v0.getOpcode()==Opcodes.ALOAD&&v0.var==0))throw new AssertionError("WORLD transfer shape");m.instructions.remove(pet);m.instructions.remove(pc);m.instructions.remove(call);changed++;}
   }if(transfers!=2)throw new AssertionError("SUMMON/WORLD transfer count "+transfers);
   for(var create:c.methods)if(create.name.equals("createTamedCompanion")&&create.desc.contains("ClassicWorldMonsterPopulation$Snapshot"))for(var i:create.instructions.toArray())if(i instanceof MethodInsnNode call&&call.name.equals("tamedFromClassicWorld")){create.instructions.insertBefore(call,new VarInsnNode(Opcodes.ALOAD,0));call.owner=P+"NativeTamedCaptureLifecycle";call.name="create";call.desc="(JL"+P+"ClassicWorldMonsterPopulation$Snapshot;IL"+P+"SourceNpcPhysicalStats;L"+P+"ClientSession;)L"+P+"BattleCompanion;";changed++;}
   m=method(c,"distributeClassicWorldMonsterDrops");for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.name.equals("activeMagicDollPowers")){var before=prev(i);if(!(before instanceof VarInsnNode v&&v.var==0))throw new AssertionError();var add=new InsnList();var keep=new LabelNode();add.add(new VarInsnNode(Opcodes.ALOAD,0));add.add(new VarInsnNode(Opcodes.ALOAD,1));add.add(new MethodInsnNode(Opcodes.INVOKESTATIC,P+"NativeTamedCaptureLifecycle","initializedDrop","(L"+P+"ClientSession;L"+P+"ClassicWorldMonsterPopulation$Snapshot;)Z",false));add.add(new JumpInsnNode(Opcodes.IFEQ,keep));add.add(new InsnNode(Opcodes.RETURN));add.add(keep);add.add(new FrameNode(Opcodes.F_SAME,0,null,0,null));m.instructions.insertBefore(before,add);changed++;}
   for(var body:c.methods)for(var i:body.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(P+"GameHub")&&call.name.equals("captureClassicWorldMonster")){body.instructions.insertBefore(call,new VarInsnNode(Opcodes.ALOAD,0));call.setOpcode(Opcodes.INVOKESTATIC);call.owner=P+"NativeTamedCaptureLifecycle";call.name="capture";call.desc="(L"+P+"GameHub;IIJL"+P+"ClientSession;)L"+P+"ClassicWorldMonsterPopulation$Capture;";changed++;}
   if(changed!=5)throw new AssertionError("PC edge count "+changed);
  }else if(c.name.endsWith("$TamedRelease")){
   var m=method(c,"<init>");for(var i:m.instructions.toArray())if(i instanceof JumpInsnNode jump&&jump.getOpcode()==Opcodes.IFNE&&prev(i).getOpcode()==Opcodes.LCMP){jump.setOpcode(Opcodes.IFEQ);changed++;}if(changed!=1)throw new AssertionError("new identity invariant "+changed);
  }else if(c.name.endsWith("$Snapshot")){
   c.fields.add(new FieldNode(Opcodes.ACC_PRIVATE|Opcodes.ACC_VOLATILE,"nativeTamedCapturePreparation","Ljava/lang/Object;",null,null));
   for(var m:c.methods)if(m.name.equals("<init>"))for(var i:m.instructions.toArray())if(i.getOpcode()==Opcodes.IF_ICMPGT){var b=prev(i);var a=prev(b);if(a instanceof VarInsnNode av&&b instanceof VarInsnNode bv&&av.getOpcode()==Opcodes.ILOAD&&bv.getOpcode()==Opcodes.ILOAD&&((av.var==10&&bv.var==11)||(av.var==12&&bv.var==13))){m.instructions.set(i,new InsnNode(Opcodes.POP2));changed++;}}if(changed!=2)throw new AssertionError("direct vital upper bounds "+changed);
  }else if(c.name.equals(P+"BattleCompanion")){c.fields.add(new FieldNode(Opcodes.ACC_PRIVATE,"nativeTamedCapturePopulation","Ljava/lang/Object;",null,null));
  }else if(c.name.endsWith("$Actor")){c.fields.add(new FieldNode(0,"nativeTamedDropInitialized","Z",null,null));c.fields.add(new FieldNode(0,"nativeTamedRespawnGeneration","J",null,null));
  }else if(c.name.equals(P+"ClassicWorldMonsterPopulation")){var m=method(c,"respawn");for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.name.equals("resetRuntimeAppearance")){var actor=prev(i);if(!(actor instanceof VarInsnNode v&&v.getOpcode()==Opcodes.ALOAD))throw new AssertionError("respawn actor shape");var add=new InsnList();add.add(new VarInsnNode(Opcodes.ALOAD,((VarInsnNode)actor).var));add.add(new InsnNode(Opcodes.ICONST_0));add.add(new FieldInsnNode(Opcodes.PUTFIELD,P+"ClassicWorldMonsterPopulation$Actor","nativeTamedDropInitialized","Z"));add.add(new VarInsnNode(Opcodes.ALOAD,((VarInsnNode)actor).var));add.add(new MethodInsnNode(Opcodes.INVOKESTATIC,H,"retireRespawn","(Ljava/lang/Object;)V",false));m.instructions.insert(call,add);changed++;}if(changed!=1)throw new AssertionError("respawn drop initialization reset "+changed);
  }else throw new AssertionError(c.name);
 }
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[1])){for(var n:List.of("ClientSession","ClassicWorldMonsterPopulation$TamedRelease","ClassicWorldMonsterPopulation$Snapshot","BattleCompanion","ClassicWorldMonsterPopulation$Actor","ClassicWorldMonsterPopulation")){var c=read(j,n);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var p=Path.of(args[2]).resolve(P+n+".class");Files.createDirectories(p.getParent());Files.write(p,expected);}else try(var out=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(out,n))))throw new AssertionError("exact selective regeneration "+n);}}}System.out.println("PASS exact regeneration: existing WORLD capture and release, carried-loot consumer, new-ID invariant, direct vital bounds, NPC-only ephemeral lifecycle fields");}
}
